.vc-vote-progress-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
  color: rgba(226, 232, 240, 0.82);
  font-size: 0.98rem;
  font-weight: 600;
}

.vc-vote-progress-bar {
  height: 0.9rem;
  overflow: hidden;
  border-radius: 9999px;
  background: rgba(var(--vc-mocha-rgb), 0.34);
}

.vc-vote-progress-fill {
  position: relative;
  display: block;
  height: 100%;
  border-radius: inherit;
  overflow: hidden;
  transform: none;
  will-change: auto;
  background: linear-gradient(
    90deg,
    rgba(var(--vc-mocha-rgb), 0.84) 0%,
    rgba(var(--vc-sand-rgb), 0.86) 55%,
    rgba(255, 247, 236, 0.98) 100%
  );
  box-shadow: 0 0 16px rgba(var(--vc-sand-rgb), 0.24);
  /* voteProgressFlow4: fill ferma; solo glow interno scorre */
  animation: none;
}

.vc-vote-progress-fill::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  width: min(38%, 2.4rem);
  border-radius: inherit;
  pointer-events: none;
  z-index: 2;
  background: linear-gradient(
    90deg,
    rgba(255, 247, 236, 0) 0%,
    rgba(255, 247, 236, 0.42) 50%,
    rgba(255, 255, 255, 0.78) 100%
  );
  opacity: 0.85;
  animation: none;
}

.vc-vote-progress-fill::after {
  content: "";
  position: absolute;
  top: -50%;
  bottom: -50%;
  left: -60%;
  width: 220%;
  border-radius: inherit;
  pointer-events: none;
  z-index: 1;
  background:
    linear-gradient(
      90deg,
      rgba(255, 247, 236, 0) 0%,
      rgba(255, 247, 236, 0) 38%,
      rgba(255, 255, 255, 0.38) 50%,
      rgba(255, 247, 236, 0) 62%,
      rgba(255, 247, 236, 0) 100%
    ),
    repeating-linear-gradient(
      90deg,
      rgba(255, 247, 236, 0) 0,
      rgba(255, 247, 236, 0) 12px,
      rgba(255, 247, 236, 0.2) 12px,
      rgba(255, 247, 236, 0.2) 20px
    );
  transform: skewX(-22deg) translate3d(0, 0, 0);
  animation: vc-vote-progress-glow-flow 1.35s linear infinite;
  mix-blend-mode: soft-light;
  will-change: transform;
}

.vc-vote-progress-fill.is-full {
  animation: none;
}

.vc-vote-progress-fill.is-full::before {
  animation: none;
  opacity: 1;
}

.vc-vote-progress-fill.is-full::after {
  animation: vc-vote-progress-glow-flow 1.05s linear infinite;
}

